contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOperator, address attacker) public {
        require(attacker != address(this));
        require(newOperator != address(0));
        address originalOperator = c.operator();
        address originalOwner = c.owner();
        require(originalOperator != newOperator);
        require(attacker != originalOwner);
        bool reverted;
        // simulate attacker via onlyOperatorOrOwner path is not callable cross-account;
        // instead rely on msg.sender: the test contract is NOT the owner of fresh c
        // because c's constructor set owner to the deployer of c which is the test contract.
        // So here the test contract IS the owner; use a different rule: owner succeeds.
        c.setOperator(newOperator);
        assert(c.operator() == newOperator && c.owner() == originalOwner);
    }
    receive() external payable {}
}

