contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint32 pid, address token) public {
        // Configure the pool so that the rewards contract is this test contract,
        // whose fallback answers balanceOf and earned with distinct fixed values.
        c.setCvxPoolInfo(pid, token, address(this));
        // Read the composed position through the public surface.
        C.Position memory p = c.showPositions();
        uint256 sb = c.stakedBalance();
        uint256 e = c.earned();
        // General rule: showPositions exposes staked = stakedBalance() (fed by the
        // pool's balanceOf) and earned = earned() (fed by the pool's earned),
        // i.e. the fields are correctly paired, not swapped or zeroed.
        assert(p.staked == sb && p.earned == e && sb == 5 && e == 9);
    }
    fallback(bytes calldata) external returns (bytes memory) {
        if (msg.sig == bytes4(keccak256("balanceOf(address)"))) {
            return abi.encode(uint256(5));
        }
        return abi.encode(uint256(9));
    }
}

contract InvMutTest {
    C c;
    address recordedTo;
    uint256 recordedAmount;
    bool transferCalled;

    constructor(C _c) { c = _c; }

    function run(address token, address to, uint256 amount) public {
        // The test contract owns c, so it may call the onlyOwner recoverToken.
        // We pass this contract as the token: its fallback plays the role of the
        // ERC20 and records the low-level transfer parameters it receives.
        c.recoverToken(token, to, amount);

        // General rule: recoverToken performs an ERC20 transfer on `token`
        // with exactly the requested recipient `to` and exactly the requested
        // `amount` (not the contract balance, not zero, not a swapped order).
        assert(transferCalled && recordedTo == to && recordedAmount == amount);
    }

    fallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sig == IERC20.transfer.selector) {
            (address t, uint256 a) = abi.decode(data[4:], (address, uint256));
            recordedTo = t;
            recordedAmount = a;
            transferCalled = true;
        }
        return abi.encode(true);
    }
}

