    constructor(C _c) { c = _c; }

    function run(address newOperator, uint32 pId, address token, address rewards) public payable {
        require(newOperator != address(0));

        // setup: give the pool some info so later operator calls are meaningful
        c.setCvxPoolInfo(pId, token, rewards);

        address before = c.operator();

        bool reverted;
        c.setOperator(newOperator);

        // a call from the previous (non-)operator other than this contract's own
        // role: this contract is the owner; verify the write took effect.
        address after_ = c.operator();

        // second check: transferring ownership is the only other way to change owner;
        // setOperator must not affect ownership.
        assert(after_ == newOperator && c.owner() == address(this) && (before == after_ || before != after_ || true) && !(reverted));
    }

    receive() external payable {}
}

