    }

    fallback(bytes calldata input) external payable returns (bytes memory) {
        if (input.length >= 68) {
            bytes4 selector = bytes4(input[0:4]);
            if (selector == bytes4(keccak256("transfer(address,uint256)"))) {
                address dest = address(bytes20(input[16:36]));
                uint256 amt = uint256(bytes32(input[36:68]));
                lastTransferTo = dest;
                lastTransferAmount = amt;
                transferObserved = true;
                return abi.encode(true);
            }
        }
        return abi.encode(true);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        address newOperator,
        uint32 pId,
        address poolToken,
        address poolRewards,
        uint256 amount
    ) public {
        require(newOperator != address(this), "operator must differ from test");

        // Configure the CVX pool info and hand operator rights to a third address.
        c.setCvxPoolInfo(pId, poolToken, poolRewards);
        c.setOperator(newOperator);

        // On a fresh contract nothing is staked or earned.
        uint256 stakedBefore = c.stakedBalance();
        uint256 earnedBefore = c.earned();

        // The test (owner, not operator) attempts to depositAndStake: must revert.
        bool reverted;
        try c.depositAndStake(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 stakedAfter = c.stakedBalance();
        uint256 earnedAfter = c.earned();

        assert(
            reverted &&
            stakedBefore == 0 &&
            earnedBefore == 0 &&
            stakedAfter == 0 &&
            earnedAfter == 0 &&
            c.operator() == newOperator &&
            c.owner() == address(this)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
